import click
from click.testing import CliRunner

class CustomArgument(click.Argument):
    pass

def test_same_decorator_object_twice():
    deco = click.argument("x", cls=CustomArgument)

    @click.command()
    @deco
    def c1(x):
        pass

    @click.command()
    @deco
    def c2(x):
        pass

    assert isinstance(c1.params[0], CustomArgument)
    assert isinstance(c2.params[0], CustomArgument)

def test_factory_used_twice():
    def deco(*a, **kw):
        return click.argument(*a, cls=CustomArgument, **kw)

    @click.command()
    @deco("x")
    def c1(x):
        pass

    @click.command()
    @deco("y")
    def c2(y):
        pass

    assert isinstance(c1.params[0], CustomArgument)
    assert isinstance(c2.params[0], CustomArgument)

def test_stacked_on_one_command():
    @click.command()
    @click.argument("x", cls=CustomArgument)
    @click.argument("y", cls=CustomArgument)
    def c(x, y):
        click.echo(f"{x},{y}")

    assert all(isinstance(p, CustomArgument) for p in c.params)
    r = CliRunner().invoke(c, ["a", "b"])
    assert r.exit_code == 0, r.output
    assert r.output.strip() == "a,b"

def test_attrs_not_mutated():
    attrs = {"cls": CustomArgument}
    deco = click.argument("x", **attrs)
    assert attrs == {"cls": CustomArgument}
